DO $$ BEGIN
  IF to_regclass('backup_cym_sv2_newpairing_468') IS NOT NULL THEN RAISE EXCEPTION 'already applied (backup_cym_sv2_newpairing_468 exists)'; END IF;
  IF (SELECT count(*) FROM flip f JOIN course_legos l ON l.course_code='cym_sv2_for_eng' AND l.seed_number=f.seed_number
        AND l.lego_index=f.lego_index AND l.target_text=f.target_text AND NOT l.is_new) <> (SELECT count(*) FROM flip) THEN
    RAISE EXCEPTION 'a listed LEGO is missing, has other text, or is still new'; END IF;
  IF EXISTS (SELECT 1 FROM add_rows a JOIN course_practice_phrases p ON p.id=a.id OR (p.course_code='cym_sv2_for_eng'
        AND p.seed_number=a.seed_number AND p.lego_index=a.lego_index AND p.position=a.position)) THEN
    RAISE EXCEPTION 'a phrase id or position is already taken: regenerate the SQL'; END IF;
  IF (SELECT count(*) FROM add_rows a JOIN course_legos l ON l.course_code='cym_sv2_for_eng' AND l.seed_number=a.seed_number
        AND l.lego_index=a.lego_index AND l.is_new) <> (SELECT count(*) FROM add_rows) THEN
    RAISE EXCEPTION 'a host LEGO is not new: its phrases would never play (P25)'; END IF;
END $$;

